class Solution {
public:
    int minOperations(std::vector<int>& nums, int x, int y) {
        long long diff = x - y;
        long long low = 1, high = *std::max_element(nums.begin(), nums.end());
        while (low < high) {
            long long mid = (low + high) / 2;
            long long boosts = 0;
            for (int num : nums) {
                long long rem = num - mid * y;
                if (rem > 0) {
                    boosts += (rem + diff - 1) / diff;
                }
            }
            if (boosts <= mid) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
};

class Solution {
    public int minOperations(int[] nums, int x, int y) {
        long diff = x - y;
        long maxVal = 0;
        for (int v : nums) maxVal = Math.max(maxVal, v);
        long low = 1, high = maxVal;
        while (low < high) {
            long mid = (low + high) / 2;
            long boosts = 0;
            for (int num : nums) {
                long rem = num - mid * y;
                if (rem > 0) {
                    boosts += (rem + diff - 1) / diff;
                }
            }
            if (boosts <= mid) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return (int)low;
    }
}

var minOperations = function(nums, x, y) {
    const diff = x - y;
    let low = 1, high = Math.max(...nums);
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        let boosts = 0;
        for (const num of nums) {
            const rem = num - mid * y;
            if (rem > 0) {
                boosts += Math.ceil(rem / diff);
            }
        }
        if (boosts <= mid) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
};
